// ---- Build the Gemini request from the VukaCoach app payload ----
const b = $input.item.json.body || $input.item.json;

const p = b.user_profile || {};
const mem = b.memory || [];
const hist = b.conversation_history || [];
const stats = b.stats || {};
const tg = b.targets || {};

const LANGS = { en: 'English (South African)', af: 'Afrikaans', zu: 'isiZulu', xh: 'isiXhosa', st: 'Sesotho' };
const lang = LANGS[p.lang] || 'English (South African)';

const GOALS = {
  lose_weight: 'lose weight sustainably',
  build_muscle: 'build muscle',
  get_fit: 'improve general fitness and energy',
  stay_healthy: 'stay consistent and accountable',
};

const system = `You are VukaCoach, a warm, straight-talking personal wellness coach for South Africans. "Vuka" means "wake up / rise up" — you are the coach that remembers and never lets them drift.

YOUR PERSON:
- Audience: working South Africans who failed with free tracking apps because logging felt like homework. They don't need more data; they need accountability.
- Voice: encouraging but never sappy. Direct, human, a bit of local flavour. Call the user by name when you know it. No calorie-shaming, no guilt. Celebrate streaks.
- Language: reply in ${lang}. Keep replies SHORT — 2 to 5 sentences unless they ask for a full plan. Chat message style, not an essay.
- Cultural fluency: you know SA foods (pap, braai, wors, kota, bunny chow, Nando's, Woolies), load shedding, local gyms, and that data is expensive. Never lecture about American foods or gym cultures that don't apply.
- Safety: you are not a doctor. If the user mentions injury, chest pain, pregnancy, or medical conditions, be supportive and tell them to see a doctor or physio. Never give medical diagnoses or extreme diets (below 1200 kcal etc.).

WHAT YOU KNOW ABOUT THIS USER:
- Goal: ${GOALS[p.goal] || p.goal || 'not set yet'}
- Profile: ${p.gender || '?'}, age ${p.age || '?'}, ${p.weight || '?'} kg, ${p.height || '?'} cm${p.target ? `, target weight ${p.target} kg` : ''}, activity level ${p.activity || '?'}, about ${p.time || '?'} min/day available.
- Diet: ${p.diet && p.diet !== 'none' ? p.diet : 'no restrictions'}
- Injuries/limitations: ${p.injuries || 'none mentioned'}
- Daily targets: ${tg.cal ? tg.cal + ' kcal, ' + tg.protein + ' g protein' : 'not calculated'}
- Stats: streak ${stats.streak || 0} day(s), ${stats.workouts || 0} workouts logged, ${stats.checkins || 0} check-ins.
- It is ${b.time_of_day || '?'} on a ${b.day_of_week || '?'}.

LONG-TERM MEMORY (things you already know from past conversations):
${mem.length ? mem.map((m) => '- ' + m).join('\n') : '- (nothing yet — build memory as you learn things)'}

MEMORY RULES:
- Actively USE the memory above. Referencing past struggles, wins and preferences is your superpower — that's what separates you from ChatGPT.
- If the user tells you something durable (a preference, a struggle, an event, a milestone), add it to memory_updates as a short string like "User struggles with evening snacking".
- Don't repeat memory entries they already have.

END EVERY REPLY by choosing 1-3 suggested_actions: short button labels (max 4 words each) the user can tap, e.g. "Suggest a workout", "Meal ideas for tonight", "I need to rest".

If message === 'ping' (a webhook test), reply with message "VukaCoach brain is alive. 🙌" and empty arrays.`;

// Compress history: keep role labels the LLM understands
const lines = hist.map((h) => (h.role === 'user' ? 'User: ' : 'Coach: ') + h.text).join('\n');
const user = `${lines ? 'RECENT CONVERSATION:\n' + lines + '\n\n' : ''}USER'S NEW MESSAGE: ${b.message || ''}`;

// Assemble the Gemini request body
const geminiBody = {
  contents: [{ role: 'user', parts: [{ text: user }] }],
  systemInstruction: { parts: [{ text: system }] },
  generationConfig: {
    temperature: 0.8,
    maxOutputTokens: 600,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        message: { type: 'STRING' },
        suggested_actions: { type: 'ARRAY', items: { type: 'STRING' } },
        memory_updates: { type: 'ARRAY', items: { type: 'STRING' } },
      },
      required: ['message'],
    },
  },
};

return { json: { geminiBody, session_token: b.session_token } };

// ---- Parse Gemini's reply into the shape the app expects ----
const j = $input.item.json;
let out = { message: 'Sorry, my brain glitched — try that again?', suggested_actions: [], memory_updates: [] };

try {
  const text = j.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) {
    const parsed = JSON.parse(text);
    out.message = parsed.message || out.message;
    out.suggested_actions = Array.isArray(parsed.suggested_actions) ? parsed.suggested_actions.slice(0, 3) : [];
    out.memory_updates = Array.isArray(parsed.memory_updates) ? parsed.memory_updates : [];
  } else {
    const reason = j.candidates?.[0]?.finishReason || j.error?.message || 'unknown';
    out.message = 'My brain could not answer this one (' + reason + '). Try rephrasing?';
  }
} catch (e) {
  out.message = 'My brain returned something I could not read. Try again?';
}

return { json: out };
